export default async function plan(
  { body, caption, rows, spreadsheetId, igId, acknowledge, resolution, confirmedId },
  ctx,
) {
  const { fileId, fileName, videoUrl } = body || {};
  if (!fileId || !fileName || !videoUrl || !spreadsheetId || !/^\d+$/.test(igId))
    throw Error("Missing video metadata or Instagram account");
  const u = new URL(videoUrl);
  if (u.protocol !== "https:" || u.username || u.password)
    throw Error("A public HTTPS video URL is required");
  const key = "reel:" + fileId;
  let s = await ctx.state.get(key);
  if (!s) {
    if (!caption?.trim()) throw Error("Missing caption");
    s = { fileId, fileName, videoUrl: u.href, caption, status: "ready-sheet", igId, spreadsheetId };
    await ctx.state.set(key, s);
  }
  if (
    s.fileId !== fileId ||
    s.fileName !== fileName ||
    s.videoUrl !== u.href ||
    s.igId !== igId ||
    s.spreadsheetId !== spreadsheetId
  )
    throw Error("Stored video details changed");
  if (s.status.startsWith("pending-")) {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending operation " + key + " " + s.status);
    const p = s.status.slice(8);
    if (resolution === "absent") s.status = "ready-" + p;
    else if (p === "sheet") s.status = "ready-create";
    else if (p === "create") {
      if (!/^\d+$/.test(confirmedId)) throw Error("Provide confirmed container ID");
      s.containerId = confirmedId;
      s.status = "ready-status";
    } else if (p === "publish") {
      s.status = "done";
    }
    await ctx.state.set(key, s);
  }
  let phase = s.status.replace("ready-", "");
  if (phase === "done")
    return {
      key,
      phase: "done",
      url: "https://graph.facebook.com",
      payload: {},
      mode: "append",
      range: "Posts!A:E",
      values: [],
      spreadsheetId,
      containerId: s.containerId || "",
      caption: s.caption,
    };
  if (!["sheet", "create", "status", "publish"].includes(phase)) throw Error("Unexpected state");
  const header = rows?.[0] || [],
    ix = header.indexOf("File ID");
  if (phase === "sheet" && ix < 0) throw Error("Missing File ID column");
  const matches = (rows || [])
    .slice(1)
    .map((x, i) => ({ x, i: i + 2 }))
    .filter((v) => v.x[ix] === fileId);
  if (matches.length > 1) throw Error("Duplicate File ID");
  let range = matches.length ? `Posts!A${matches[0].i}:E${matches[0].i}` : "Posts!A:E",
    values = [[fileId, fileName, s.caption, u.href, body.thumbnailUrl || ""]],
    mode = matches.length ? "update" : "append",
    url =
      "https://graph.facebook.com/v22.0/" +
      (phase === "status"
        ? s.containerId
        : igId + "/" + (phase === "publish" ? "media_publish" : "media")),
    payload =
      phase === "create"
        ? { media_type: "REELS", video_url: u.href, caption: s.caption }
        : phase === "publish"
          ? { creation_id: s.containerId }
          : {};
  if (phase !== "status") {
    s.status = "pending-" + phase;
    await ctx.state.set(key, s);
  }
  return {
    key,
    phase,
    url,
    payload,
    mode,
    range,
    values,
    spreadsheetId,
    containerId: s.containerId || "",
    caption: s.caption,
  };
}

