async function confirm(
  { key, kind, body, statusCode, spreadsheetId, actualSpreadsheetId, updatedRows },
  ctx,
) {
  const s = await ctx.state.get(key);
  if (!s) throw Error("Missing state");
  if (kind === "status") {
    if (statusCode < 200 || statusCode >= 300) throw Error("Unknown container status");
    if (s.status !== "ready-status" || body?.id !== s.containerId)
      throw Error("Wrong container status");
    if (body.status_code === "FINISHED") s.status = "ready-publish";
    else if (["ERROR", "EXPIRED"].includes(body.status_code))
      throw Error("Container failed; inspect Meta");
    else throw Error("Container processing; retry later");
  } else {
    if (s.status !== "pending-" + kind) throw Error("Unexpected pending write");
    if (kind === "sheet") {
      if (actualSpreadsheetId !== spreadsheetId || updatedRows !== 1)
        throw Error("Unknown sheet write");
      s.status = "ready-create";
    } else {
      if (statusCode < 200 || statusCode >= 300 || !/^\d+$/.test(body?.id || ""))
        throw Error("Unknown Meta write");
      if (kind === "create") {
        s.containerId = body.id;
        s.status = "ready-status";
      } else if (kind === "publish") {
        s.mediaId = body.id;
        s.status = "done";
      } else throw Error("Invalid stage");
    }
  }
  await ctx.state.set(key, s);
  return { ok: true };
}

export default async function f(input, ctx) {
  return confirm({ ...input, kind: "sheet" }, ctx);
}

